def _wire_integer_pairs_body(pairs: Sequence[tuple[int, int]]) -> bytes:
    """A tuple body of two-integer tuples, one per pair."""
    return _wire_tuple(
        [_wire_tuple([_wire_int(pair[0]), _wire_int(pair[1])]) for pair in pairs]
    )


def _wire_interval_range_proof_body(proof: IntervalRangeProof) -> bytes:
    """An IntervalRangeProof body: its six tuples, in field order."""
    return _wire_tuple(
        [
            _wire_tuple([_wire_int(item) for item in proof.low_commitments]),
            _wire_integer_pairs_body(proof.low_challenges),
            _wire_integer_pairs_body(proof.low_responses),
            _wire_tuple([_wire_int(item) for item in proof.high_commitments]),
            _wire_integer_pairs_body(proof.high_challenges),
            _wire_integer_pairs_body(proof.high_responses),
        ]
    )


def _check_commitment_types(commitment: object, name: str) -> None:
    if not isinstance(commitment, PedersenCommitment):
        raise TypeError(f"{name} must be a PedersenCommitment")
    for field_name in _COMMITMENT_FIELDS:
        _check_int(getattr(commitment, field_name), f"{name} {field_name}")


def _check_range_proof_types(proof: object, name: str) -> None:
    if not isinstance(proof, RangeProof):
        raise TypeError(f"{name} must be a RangeProof")
    for field_name in ("t", "e", "s"):
        field = getattr(proof, field_name)
        if not isinstance(field, tuple):
            raise TypeError(f"{name} {field_name} must be a tuple of integers")
        for position, item in enumerate(field):
            _check_int(item, f"{name} {field_name}[{position}]")


def _check_bundle_wide_range_proof(proof: object, name: str) -> None:
    if not isinstance(proof, WideRangeProof):
        raise TypeError(f"{name} must be a WideRangeProof")
    if not isinstance(proof.commitments, tuple):
        raise TypeError(f"{name} commitments must be a tuple of integers")
    for position, item in enumerate(proof.commitments):
        _check_int(item, f"{name} commitments[{position}]")
    for field_name in ("challenges", "responses"):
        field = getattr(proof, field_name)
        if not isinstance(field, tuple):
            raise TypeError(f"{name} {field_name} must be a tuple of integer pairs")
        for index, pair in enumerate(field):
            if not isinstance(pair, tuple):
                raise TypeError(
                    f"{name} {field_name} must be a tuple of integer pairs"
                )
            if len(pair) != 2:
                raise TypeError(
                    f"{name} {field_name}[{index}] must be an integer pair"
                )
            _check_int(pair[0], f"{name} {field_name}[{index}][0]")
            _check_int(pair[1], f"{name} {field_name}[{index}][1]")


_INTERVAL_RANGE_PROOF_PAIR_FIELDS = (
    "low_challenges",
    "low_responses",
    "high_challenges",
    "high_responses",
)


def _check_bundle_interval_range_proof(proof: object, name: str) -> None:
    """Full encode-time check of one :class:`IntervalRangeProof`.

    Nested type errors (wrong object, non-tuple fields, non-integer or
    ``bool`` entries) raise :class:`TypeError` via
    :func:`_check_interval_range_proof_types`; with types established, a
    proof whose six fields differ in length, whose common length falls
    outside ``1.._MAX_INTERVAL_RANGE_BITS`` or whose challenge/response
    entries are not integer pairs raises :class:`ValueError`.
    """
    _check_interval_range_proof_types(proof, name)
    width = len(proof.low_commitments)
    field_names = (
        "low_commitments",
        "low_challenges",
        "low_responses",
        "high_commitments",
        "high_challenges",
        "high_responses",
    )
    if any(len(getattr(proof, field_name)) != width for field_name in field_names):
        raise ValueError(
            f"{name} interval range proof fields must be equal-length tuples"
        )
    if not 1 <= width <= _MAX_INTERVAL_RANGE_BITS:
        raise ValueError(
            f"{name} interval range proof must hold "
            f"1..{_MAX_INTERVAL_RANGE_BITS} matching bit entries"
        )
    for field_name in _INTERVAL_RANGE_PROOF_PAIR_FIELDS:
        for index, pair in enumerate(getattr(proof, field_name)):
            if len(pair) != 2:
                raise ValueError(
                    f"{name} {field_name}[{index}] must be an integer pair"
                )


class _ProofStructureReader(_WireReader):
    """Wire reader that rebuilds the shared commitment/sub-proof structures."""

    def commitment(self, what: str) -> PedersenCommitment:
        body = self.frame(what)
        inner = _ProofStructureReader(body)
        count = inner.tuple_cardinality(what)
        if count != 6:
            raise ValueError(f"{what} commitment must have exactly six fields")
        values = [
            inner.int_value(f"{what} {name}") for name in _COMMITMENT_FIELDS
        ]
        if not inner.at_end():
            raise ValueError(f"{what} commitment has trailing data")
        element, lower, upper, prime, generator, h = values
        if prime <= 3:
            raise ValueError(f"{what} prime must be greater than 3")
        if not 1 < generator < prime:
            raise ValueError(f"{what} generator must satisfy 1 < generator < prime")
        if not 1 < h < prime:
            raise ValueError(f"{what} h must satisfy 1 < h < prime")
        if not 0 < element < prime:
            raise ValueError(f"{what} element must satisfy 0 < element < prime")
        if lower > upper:
            raise ValueError(f"{what} lower must not exceed upper")
        if upper - lower >= prime - 1:
            raise ValueError(f"{what} range width must be smaller than prime - 1")
        return PedersenCommitment(*values)

    def range_proof(self, what: str) -> RangeProof:
        body = self.frame(what)
        inner = _ProofStructureReader(body)
        count = inner.tuple_cardinality(what)
        if count != 3:
            raise ValueError(f"{what} range proof must have exactly three fields")
        t = inner.integer_tuple(f"{what} t")
        e = inner.integer_tuple(f"{what} e")
        s = inner.integer_tuple(f"{what} s")
        if not inner.at_end():
            raise ValueError(f"{what} range proof has trailing data")
        size = len(t)
        if not (1 <= size <= _MAX_RANGE_VALUES) or not (
            len(e) == size and len(s) == size
        ):
            raise ValueError(
                f"{what} range proof fields must be equal-length tuples of "
                f"1..{_MAX_RANGE_VALUES} integers"
            )
        return RangeProof(t=t, e=e, s=s)

    def wide_range_proof(self, what: str) -> WideRangeProof:
        body = self.frame(what)
        inner = _ProofStructureReader(body)
        count = inner.tuple_cardinality(what)
        if count != 3:
            raise ValueError(f"{what} wide range proof must have three fields")
        commitments = inner.integer_tuple(f"{what} commitments")
        pairs: dict[str, list[tuple[int, int]]] = {}
        for field_name in ("challenges", "responses"):
            pair_body = inner.frame(f"{what} {field_name}")
            pair_reader = _WireReader(pair_body)
            pair_count = pair_reader.tuple_cardinality(f"{what} {field_name}")
            decoded_pairs: list[tuple[int, int]] = []
            for index in range(pair_count):
                item_body = pair_reader.frame(f"{what} {field_name}[{index}]")
                item_reader = _WireReader(item_body)
                item_count = item_reader.tuple_cardinality(
                    f"{what} {field_name}[{index}]"
                )
                if item_count != 2:
                    raise ValueError(
                        f"{what} {field_name}[{index}] must be an integer pair"
                    )
                first = item_reader.int_value(f"{what} {field_name}[{index}][0]")
                second = item_reader.int_value(f"{what} {field_name}[{index}][1]")
                if not item_reader.at_end():
                    raise ValueError(
                        f"{what} {field_name}[{index}] has trailing data"
                    )
                decoded_pairs.append((first, second))
            if not pair_reader.at_end():
                raise ValueError(f"{what} {field_name} has trailing data")
            pairs[field_name] = decoded_pairs
        if not inner.at_end():
            raise ValueError(f"{what} wide range proof has trailing data")
        width = len(commitments)
        if not (
            1 <= width <= _MAX_WIDE_RANGE_BITS
            and len(pairs["challenges"]) == width
            and len(pairs["responses"]) == width
        ):
            raise ValueError(
                f"{what} wide range proof must hold 1..{_MAX_WIDE_RANGE_BITS} "
                "matching bit entries"
            )
        return WideRangeProof(
            commitments=commitments,
            challenges=tuple(pairs["challenges"]),
            responses=tuple(pairs["responses"]),
        )

    def interval_range_proof(self, what: str) -> IntervalRangeProof:
        body = self.frame(what)
        inner = _ProofStructureReader(body)
        count = inner.tuple_cardinality(what)
        if count != 6:
            raise ValueError(
                f"{what} interval range proof must have exactly six fields"
            )
        low_commitments = inner.integer_tuple(f"{what} low_commitments")
        low_challenges = inner.integer_pair_tuple(f"{what} low_challenges")
        low_responses = inner.integer_pair_tuple(f"{what} low_responses")
        high_commitments = inner.integer_tuple(f"{what} high_commitments")
        high_challenges = inner.integer_pair_tuple(f"{what} high_challenges")
        high_responses = inner.integer_pair_tuple(f"{what} high_responses")
        if not inner.at_end():
            raise ValueError(f"{what} interval range proof has trailing data")
        width = len(low_commitments)
        if not (
            1 <= width <= _MAX_INTERVAL_RANGE_BITS
            and len(low_challenges) == width
            and len(low_responses) == width
            and len(high_commitments) == width
            and len(high_challenges) == width
            and len(high_responses) == width
        ):
            raise ValueError(
                f"{what} interval range proof must hold "
                f"1..{_MAX_INTERVAL_RANGE_BITS} matching bit entries"
            )
        return IntervalRangeProof(
            low_commitments=low_commitments,
            low_challenges=low_challenges,
            low_responses=low_responses,
            high_commitments=high_commitments,
            high_challenges=high_challenges,
            high_responses=high_responses,
        )


# ---------------------------------------------------------------------------
# Canonical binary envelope for cross-process region proof transport
#
# A RegionProofBundle freezes the five verification-relevant objects (both
# PedersenCommitment objects, the Region, the external context and the
# RegionProof / RegionWideProof / RegionIntervalProof) into a
# self-describing byte string. The wire
# format is versioned and proof-type tagged; it composes the generic wire
# primitives and shared proof structures above.
#
# Layout (all integers in the framing headers are unsigned big-endian):
#
#   magic (4) || version (1) || proof_type (1)
#   frame(x_commitment) || frame(y_commitment) || frame(region)
#   frame(context) || frame(proof)
#
# Structured bodies carry an explicit tuple cardinality; the one-byte
# proof-type tag in the header makes RegionProof, RegionWideProof and
# RegionIntervalProof byte-distinguishable, and the proof body is always
# the two axis sub-proofs in (x, y) order.

_REGION_BUNDLE_MAGIC = b"zrgn"
_REGION_BUNDLE_VERSION = 1
_REGION_BUNDLE_PROOF_TYPE_RANGE = 1
_REGION_BUNDLE_PROOF_TYPE_WIDE = 2
_REGION_BUNDLE_PROOF_TYPE_INTERVAL = 3


@dataclass(frozen=True)
class RegionProofBundle:
    """A versioned, canonical binary envelope for one region proof.

    Fields, in the fixed wire order: ``x_commitment`` / ``y_commitment``
    (:class:`PedersenCommitment`), ``region`` (:class:`Region`),
    ``context`` (``bytes``) and ``proof`` (a :class:`RegionProof`,
    :class:`RegionWideProof` or :class:`RegionIntervalProof`). Bundles are
    positional construction arguments, compare by value and are immutable;
    construction performs no validation — use
    :func:`encode_region_proof_bundle` /
    :func:`verify_region_proof_bundle` to check.
    """

    x_commitment: PedersenCommitment
    y_commitment: PedersenCommitment
    region: Region
    context: bytes
    proof: RegionProof | RegionWideProof | RegionIntervalProof


def _wire_region_body(region: Region) -> bytes:
    """A Region body: its four bounds in field order (min_x, max_x, min_y, max_y)."""
    return _wire_tuple(
        [
            _wire_int(getattr(region, name))
            for name in ("min_x", "max_x", "min_y", "max_y")
        ]
    )


def _region_proof_body_and_tag(
    proof: RegionProof | RegionWideProof | RegionIntervalProof,
) -> tuple[int, bytes]:
    """Return ``(proof_type_tag, proof body)`` for the region bundle payload.

    The proof body is a two-item tuple (the x then the y axis sub-proof);
    the type tag lives in the envelope header next to the format version.
    """
    if isinstance(proof, RegionProof):
        body = _wire_tuple(
            [
                _wire_range_proof_body(proof.x_proof),
                _wire_range_proof_body(proof.y_proof),
            ]
        )
        return _REGION_BUNDLE_PROOF_TYPE_RANGE, body
    if isinstance(proof, RegionWideProof):
        body = _wire_tuple(
            [
                _wire_wide_range_proof_body(proof.x_proof),
                _wire_wide_range_proof_body(proof.y_proof),
            ]
        )
        return _REGION_BUNDLE_PROOF_TYPE_WIDE, body
    body = _wire_tuple(
        [
            _wire_interval_range_proof_body(proof.x_proof),
            _wire_interval_range_proof_body(proof.y_proof),
        ]
    )
    return _REGION_BUNDLE_PROOF_TYPE_INTERVAL, body


def _check_region_types(region: object, *, enforce_order: bool) -> None:
    if not isinstance(region, Region):
        raise TypeError("region must be a Region")
    for field_name in ("min_x", "max_x", "min_y", "max_y"):
        _check_int(getattr(region, field_name), f"region {field_name}")
    if enforce_order and (
        region.min_x > region.max_x or region.min_y > region.max_y
    ):
        raise ValueError("region bounds must satisfy min <= max on each axis")


def encode_region_proof_bundle(bundle: RegionProofBundle) -> bytes:
    """Encode a :class:`RegionProofBundle` into its canonical byte envelope.

    The same bundle object always encodes to the same byte string. The
    output starts with the four-byte magic ``b"zrgn"``, a one-byte format
    version and a one-byte proof-type tag, followed by the five fields in
    fixed order (``x_commitment``, ``y_commitment``, ``region``,
    ``context``, ``proof``); each item is length-prefixed with a four-byte
    big-endian header. Arbitrary-precision integers (including negative
    bounds) carry a sign byte and a shortest big-endian magnitude; tuples
    carry an explicit cardinality. The function returns ``bytes`` only and
    never writes to the file system or a database.

    A wrong object or field type (including a ``bool`` integer, a
    non-tuple proof field, a wide-proof pair that is not a two-tuple, or a
    proof that is neither a :class:`RegionProof` nor a
    :class:`RegionWideProof` nor a :class:`RegionIntervalProof`) raises
    :class:`TypeError`. An interval proof whose six fields differ in
    length, whose common length falls outside ``1..24`` or whose
    challenge/response entries are not integer pairs raises
    :class:`ValueError`. A region with ``min > max`` on an axis cannot be
    built through the public :class:`Region` constructor; if such an
    object is forged bypassing the constructor, it is rejected with
    :class:`ValueError`.
    """
    if not isinstance(bundle, RegionProofBundle):
        raise TypeError("bundle must be a RegionProofBundle")
    _check_commitment_types(bundle.x_commitment, "x_commitment")
    _check_commitment_types(bundle.y_commitment, "y_commitment")
    _check_region_types(bundle.region, enforce_order=True)
    if not isinstance(bundle.context, bytes):
        raise TypeError("context must be bytes")
    proof = bundle.proof
    if isinstance(proof, RegionProof):
        _check_range_proof_types(proof.x_proof, "proof x_proof")
        _check_range_proof_types(proof.y_proof, "proof y_proof")
    elif isinstance(proof, RegionWideProof):
        _check_bundle_wide_range_proof(proof.x_proof, "proof x_proof")
        _check_bundle_wide_range_proof(proof.y_proof, "proof y_proof")
    elif isinstance(proof, RegionIntervalProof):
        _check_bundle_interval_range_proof(proof.x_proof, "proof x_proof")
        _check_bundle_interval_range_proof(proof.y_proof, "proof y_proof")
    else:
        raise TypeError(
            "proof must be a RegionProof, RegionWideProof or RegionIntervalProof"
        )
    proof_type, proof_body = _region_proof_body_and_tag(proof)
    out = bytearray()
    out += _REGION_BUNDLE_MAGIC
    out += bytes((_REGION_BUNDLE_VERSION, proof_type))
    out += _wire_frame(_wire_commitment_body(bundle.x_commitment))
    out += _wire_frame(_wire_commitment_body(bundle.y_commitment))
    out += _wire_frame(_wire_region_body(bundle.region))
    out += _wire_frame(bundle.context)
    out += _wire_frame(proof_body)
    return bytes(out)


class _RegionBundleReader(_ProofStructureReader):
    """Strict envelope reader for region bounds and the tagged region proof."""

    def region(self) -> Region:
        body = self.frame("region")
        inner = _RegionBundleReader(body)
        count = inner.tuple_cardinality("region")
        if count != 4:
            raise ValueError("region must have exactly four bounds")
        min_x, max_x, min_y, max_y = (
            inner.int_value(f"region {name}")
            for name in ("min_x", "max_x", "min_y", "max_y")
        )
        if not inner.at_end():
            raise ValueError("region has trailing data")
        return Region(min_x=min_x, max_x=max_x, min_y=min_y, max_y=max_y)

    def proof(self, tag: int) -> RegionProof | RegionWideProof | RegionIntervalProof:
        body = self.frame("proof")
        inner = _RegionBundleReader(body)
        count = inner.tuple_cardinality("proof")
        if count != 2:
            raise ValueError("proof must have exactly two axis sub-proofs")
        if tag == _REGION_BUNDLE_PROOF_TYPE_RANGE:
            x_proof = inner.range_proof("region proof x_proof")
            y_proof = inner.range_proof("region proof y_proof")
            if not inner.at_end():
                raise ValueError("region proof has trailing data")
            return RegionProof(x_proof=x_proof, y_proof=y_proof)
        if tag == _REGION_BUNDLE_PROOF_TYPE_WIDE:
            x_proof = inner.wide_range_proof("region wide proof x_proof")
            y_proof = inner.wide_range_proof("region wide proof y_proof")
            if not inner.at_end():
                raise ValueError("region wide proof has trailing data")
            return RegionWideProof(x_proof=x_proof, y_proof=y_proof)
        if tag == _REGION_BUNDLE_PROOF_TYPE_INTERVAL:
            x_proof = inner.interval_range_proof("region interval proof x_proof")
            y_proof = inner.interval_range_proof("region interval proof y_proof")
            if not inner.at_end():
                raise ValueError("region interval proof has trailing data")
            return RegionIntervalProof(x_proof=x_proof, y_proof=y_proof)
        raise ValueError("unknown region proof bundle proof type")


def decode_region_proof_bundle(data: bytes) -> RegionProofBundle:
    """Decode a canonical envelope back into a :class:`RegionProofBundle`.

    ``data`` must be exactly the output of
    :func:`encode_region_proof_bundle`: the magic, a known format version
    and proof-type tag, and the five fields in their fixed order with
    valid length prefixes, tuple cardinalities and integer sign bytes.
    The payload must be consumed completely with no trailing bytes. A
    truncated input, an out-of-bounds length, an unknown version or proof
    type, a non-canonical integer, an illegal region or an unexpected
    nested proof shape raises :class:`ValueError`; a non-``bytes`` input
    raises :class:`TypeError`. A decoded bundle compares equal field-for-
    field to the original and a payload of one proof type can never be
    rebuilt as another (:class:`RegionProof`, :class:`RegionWideProof` and
    :class:`RegionIntervalProof` are byte-distinguishable).
    """
    if not isinstance(data, bytes):
        raise TypeError("data must be bytes")
    reader = _RegionBundleReader(data)
    reader.expect(_REGION_BUNDLE_MAGIC, "region proof bundle magic")
    version = reader.byte("format version")
    if version != _REGION_BUNDLE_VERSION:
        raise ValueError("unknown region proof bundle format version")
    tag = reader.byte("proof type")
    if tag not in (
        _REGION_BUNDLE_PROOF_TYPE_RANGE,
        _REGION_BUNDLE_PROOF_TYPE_WIDE,
        _REGION_BUNDLE_PROOF_TYPE_INTERVAL,
    ):
        raise ValueError("unknown region proof bundle proof type")
    x_commitment = reader.commitment("x_commitment")
    y_commitment = reader.commitment("y_commitment")
    region = reader.region()
    context = reader.frame("context")
    proof = reader.proof(tag)
    if not reader.at_end():
        raise ValueError("trailing data after region proof bundle payload")
    return RegionProofBundle(
        x_commitment=x_commitment,
        y_commitment=y_commitment,
        region=region,
        context=context,
        proof=proof,
    )


def verify_region_proof_bundle(bundle: RegionProofBundle) -> bool:
    """Verify the proof carried by a :class:`RegionProofBundle`.

    Verification follows the existing single-proof semantics exactly,
    dispatching on the ``proof`` type: :class:`RegionProof` is checked with
    :func:`verify_region`, :class:`RegionWideProof` with
    :func:`verify_region_wide` and :class:`RegionIntervalProof` with
    :func:`verify_region_interval`, using only the two
    :class:`PedersenCommitment` objects, the :class:`Region` and the
    ``context`` — never coordinates or blinding factors. A wrong object or
    field type (including a proof of none of the three region-proof types)
    raises :class:`TypeError`; every other failure — a declared range
    mismatch, a context mismatch, swapped axes or commitments, a tampered
    proof or a failed verification equation — returns ``False``. Encoding
    and then decoding a bundle preserves the verification verdict.
    """
    if not isinstance(bundle, RegionProofBundle):
        raise TypeError("bundle must be a RegionProofBundle")
    _check_commitment_types(bundle.x_commitment, "x_commitment")
    _check_commitment_types(bundle.y_commitment, "y_commitment")
    # Types only: illegal interval values are decided (False) by the
    # delegated single-proof verifiers, never raised here.
    _check_region_types(bundle.region, enforce_order=False)
    if not isinstance(bundle.context, bytes):
        raise TypeError("context must be bytes")
    proof = bundle.proof
    if isinstance(proof, RegionProof):
        return verify_region(
            bundle.x_commitment,
            bundle.y_commitment,
            bundle.region,
            proof,
            bundle.context,
        )
    if isinstance(proof, RegionWideProof):
        return verify_region_wide(
            bundle.x_commitment,
            bundle.y_commitment,
            bundle.region,
            proof,
            bundle.context,
        )
    if isinstance(proof, RegionIntervalProof):
        return verify_region_interval(
            bundle.x_commitment,
            bundle.y_commitment,
            bundle.region,
            proof,
            bundle.context,
        )
    raise TypeError(
        "proof must be a RegionProof, RegionWideProof or RegionIntervalProof"
    )


# ---------------------------------------------------------------------------
# Versioned binary envelope for convex polygon membership proofs
#
# A ConvexPolygonProofBundle freezes the five public inputs of
# verify_convex_polygon (both commitments, the polygon, the external
# context and the ConvexPolygonRegionProof). It composes the same generic
# wire primitives and shared proof structures as the region envelope, under
# its own magic and with no proof-type tag:
#
#   magic (4) || version (1)
#   frame(x_commitment) || frame(y_commitment) || frame(polygon)
#   frame(context) || frame(proof)
#
# The polygon body is a tuple of canonical (x, y) vertex pairs; the proof
# body is a three-item tuple — the RangeProof for the x axis, the RangeProof
# for the y axis, then a tuple of one WideRangeProof per polygon edge in
# canonical boundary order.

_CONVEX_BUNDLE_MAGIC = b"zrgp"
_CONVEX_BUNDLE_VERSION = 1


@dataclass(frozen=True)
class ConvexPolygonProofBundle:
    """A versioned, canonical binary envelope for one convex polygon proof.

_WIRE_INT_SIGN_POSITIVE = 1
_WIRE_INT_SIGN_NEGATIVE = 255


def _wire_frame(body: bytes) -> bytes:
    """One length-prefixed envelope item: four-byte big-endian length plus body."""
    return len(body).to_bytes(4, "big") + body


def _wire_int(value: int) -> bytes:
    """Canonical signed arbitrary-precision integer body (no length frame)."""
    sign = _WIRE_INT_SIGN_POSITIVE if value >= 0 else _WIRE_INT_SIGN_NEGATIVE
    magnitude = abs(value)
    return bytes((sign,)) + magnitude.to_bytes(
        max(1, (magnitude.bit_length() + 7) // 8), "big"
    )


def _wire_tuple(items: Sequence[bytes]) -> bytes:
    """A tuple body: four-byte cardinality followed by the framed items."""
    body = len(items).to_bytes(4, "big")
    for item in items:
        body += _wire_frame(item)
    return body


class _WireReader:
    """Cursor over an envelope payload with strict bounds checking.

    Every read validates its length prefix and element type before
    returning; any truncation or overflow raises :class:`ValueError`. This
    base reader implements only the generic wire syntax (raw frames,
    integers and tuple cardinalities); bundle-specific subclasses add their
    own structural constructors.
    """

    def __init__(self, data: bytes) -> None:
        self._data = data
        self._offset = 0

    def take(self, size: int) -> bytes:
        if size < 0 or self._offset + size > len(self._data):
            raise ValueError("truncated region proof bundle payload")
        chunk = self._data[self._offset : self._offset + size]
        self._offset += size
        return chunk

    def byte(self, what: str) -> int:
        return self.take(1)[0]

    def expect(self, expected: bytes, what: str) -> None:
        actual = self.take(len(expected))
        if actual != expected:
            raise ValueError(f"invalid {what}")

    def uint32(self) -> int:
        return int.from_bytes(self.take(4), "big")

    def frame(self, what: str) -> bytes:
        length = self.uint32()
        return self.take(length)

    def at_end(self) -> bool:
        return self._offset == len(self._data)

    def int_value(self, what: str) -> int:
        body = self.frame(what)
        if len(body) < 2:
            raise ValueError(f"{what} integer is too short")
        sign = body[0]
        if sign not in (_WIRE_INT_SIGN_POSITIVE, _WIRE_INT_SIGN_NEGATIVE):
            raise ValueError(f"{what} integer has an unknown sign byte")
        magnitude = int.from_bytes(body[1:], "big")
        # Canonical shortest form: no leading zero magnitude bytes and no
        # negative zero.
        if body[1] == 0 and len(body) > 2:
            raise ValueError(f"{what} integer is not in canonical form")
        if sign == _WIRE_INT_SIGN_NEGATIVE and magnitude == 0:
            raise ValueError(f"{what} integer uses a non-canonical negative zero")
        return -magnitude if sign == _WIRE_INT_SIGN_NEGATIVE else magnitude

    def tuple_cardinality(self, what: str) -> int:
        return int.from_bytes(self.take(4), "big")

    def integer_tuple(self, what: str) -> tuple[int, ...]:
        body = self.frame(what)
        inner = _WireReader(body)
        count = inner.tuple_cardinality(what)
        items = [inner.int_value(f"{what}[{i}]") for i in range(count)]
        if not inner.at_end():
            raise ValueError(f"{what} tuple has trailing data")
        return tuple(items)

    def integer_pair_tuple(self, what: str) -> tuple[tuple[int, int], ...]:
        body = self.frame(what)
        inner = _WireReader(body)
        count = inner.tuple_cardinality(what)
        pairs: list[tuple[int, int]] = []
        for index in range(count):
            item_body = inner.frame(f"{what}[{index}]")
            item_reader = _WireReader(item_body)
            item_count = item_reader.tuple_cardinality(f"{what}[{index}]")
            if item_count != 2:
                raise ValueError(f"{what}[{index}] must be an integer pair")
            first = item_reader.int_value(f"{what}[{index}][0]")
            second = item_reader.int_value(f"{what}[{index}][1]")
            if not item_reader.at_end():
                raise ValueError(f"{what}[{index}] has trailing data")
            pairs.append((first, second))
        if not inner.at_end():
            raise ValueError(f"{what} tuple has trailing data")
        return tuple(pairs)


